export function Link({
  label = "{{label}}",
  href = "{{href}}",
  external = {{external}},
  accent = "{{accent}}",
}) {
  return (
    <a
      href={href}
      target={external ? "_blank" : undefined}
      rel={external ? "noopener noreferrer" : undefined}
      style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", textDecoration: "underline", textDecorationColor: accent, textDecorationThickness: 2, textUnderlineOffset: 2 }}
    >
      {label}
      {external && (
        <>
          <span aria-hidden="true" style={{ marginLeft: 3, fontSize: 12, textDecoration: "none" }}>&#8599;</span>
          <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden", clip: "rect(0,0,0,0)", whiteSpace: "nowrap" }}> (opens in a new tab)</span>
        </>
      )}
    </a>
  );
}
